STORY = [('paquita', '¿Qué hago mal, Magüi? ¿Qué hago mal?', 'What am I doing wrong, Magüi? What am I doing wrong?', [(235, '¿Qué hago mal, Magüi? ¿Qué hago mal?')], ''), ('magui', 'Venga, Paca, ya está. Mira, vamos a recoger esto y nos vamos a poner a trabajar.', "Come on, Paca, it's okay. Look, let's tidy this up and get back to work.", [(236, 'Venga, Paca, ya está. Mira, vamos a recoger esto'), (237, 'Nos vamos a poner a trabajar')], ''), ('paquita', 'Es que se van todas, siempre igual. ¿Qué hago mal?', "They all leave me, it's always the same. What am I doing wrong?", [(238, 'Es que se van todas, siempre igual. ¿Qué hago mal?')], ''), ('magui', 'Te voy a enseñar el videobook de la prima de Álex, ya verás cómo te gusta.', "I'm going to show you the showreel of Álex's cousin—you'll see how much you like it.", [(239, 'Te voy a enseñar el videobook de la prima de Álex'), (240, 'ya verás cómo te gusta')], ''), ('paquita', '¿No te enteras? ¿Cómo vamos a ver ahora el videobook de la prima de tu novio?', "Don't you get it? How are we supposed to watch your boyfriend's cousin's showreel right now?", [(241, '¿No te enteras?'), (241, 'el videobook'), (242, 'de la prima de tu novio')], ''), ('paquita', 'Después de lo que he hecho por esa desagradecida, ahora se va.', "After everything I've done for that ungrateful girl, now she leaves.", [(242, 'Después de lo que he hecho'), (243, 'por esa desagradecida, ahora se va')], ''), ('paquita', 'Todo el año de entrevistas, alfombras rojas y los castings.', 'A whole year of interviews, red carpets, and castings.', [(243, 'Todo el año de entrevistas'), (244, 'alfombras rojas'), (244, 'los castings')], ''), ('paquita', '¿Y el vestido de los Goya? ¿Qué hago, me lo pongo y voy sola?', 'And what about my Goya dress? What do I do, put it on and go alone?', [(246, 'el vestido'), (247, '¿Qué hago, me lo pongo y voy sola?')], ''), ('paquita', 'No voy a ver ningún videobook. Lo que me voy es a mi casa.', "I'm not watching any showreel. What I'm doing is going home.", [(247, 'No voy a ver ningún videobook'), (248, 'Lo que me voy es a mi casa')], ''), ('magui', 'Pues yo lo he visto y a mí me ha gustado mucho.', "Well, I've watched it and I liked it a lot.", [(249, 'Pues yo lo he visto y a mí me ha gustado mucho')], ''), ('paquita', 'Pues que te des cuenta de que lo que a ti te guste me da igual.', "Well, realise that I couldn't care less what you like.", [(250, 'Pues que te des cuenta de que lo que a ti te guste me da igual')], ''), ('magui', '¿Pues sabes lo que pasa? Que ese es tu problema.', "Well, do you know what? That's your problem.", [(252, '¿Pues sabes lo que pasa? Que ese es tu problema')], '')]
